#include "hash160.cuh"
#include <cstdio>
#include <cstdlib>
#include <vector>
#include <cstring>
using namespace secp256k1::cuda;
__global__ void k(const uint8_t* in, int len, uint8_t* out, int n){
  int i=blockIdx.x*blockDim.x+threadIdx.x; if(i<n) hash160_pubkey(in+(size_t)i*len,(size_t)len,out+(size_t)i*20);
}
int main(int argc,char**argv){
  int len=atoi(argv[1]); int n=1<<22; int reps=atoi(argv[2]);
  std::vector<uint8_t> h((size_t)n*len); uint64_t x=88172645463325252ULL;
  for(auto&b:h){x^=x<<13;x^=x>>7;x^=x<<17;b=(uint8_t)x;}
  // known vector: generator compressed pubkey
  static const uint8_t G[33]={0x02,0x79,0xBE,0x66,0x7E,0xF9,0xDC,0xBB,0xAC,0x55,0xA0,0x62,0x95,0xCE,0x87,0x0B,0x07,0x02,0x9B,0xFC,0xDB,0x2D,0xCE,0x28,0xD9,0x59,0xF2,0x81,0x5B,0x16,0xF8,0x17,0x98};
  if(len==33) memcpy(h.data(),G,33);
  uint8_t *din,*dout; cudaMalloc(&din,h.size()); cudaMalloc(&dout,(size_t)n*20);
  cudaMemcpy(din,h.data(),h.size(),cudaMemcpyHostToDevice);
  k<<<(n+255)/256,256>>>(din,len,dout,n); cudaDeviceSynchronize();
  cudaEvent_t a,b; cudaEventCreate(&a); cudaEventCreate(&b);
  cudaEventRecord(a); for(int r=0;r<reps;++r) k<<<(n+255)/256,256>>>(din,len,dout,n); cudaEventRecord(b); cudaEventSynchronize(b);
  float ms; cudaEventElapsedTime(&ms,a,b);
  std::vector<uint8_t> o((size_t)n*20); cudaMemcpy(o.data(),dout,o.size(),cudaMemcpyDeviceToHost);
  uint64_t fnv=1469598103934665603ULL; for(auto c:o){fnv^=c;fnv*=1099511628211ULL;}
  printf("len=%d n=%d reps=%d ns_per_hash=%.4f digest=%016llx first=",len,n,reps,ms*1e6/((double)n*reps),(unsigned long long)fnv);
  for(int i=0;i<20;++i)printf("%02x",o[i]); printf(" err=%s\n",cudaGetErrorString(cudaGetLastError()));
}
